<?php require_once __DIR__.'/includes/functions.php';need_role(['petugas','admin_utama']);$where=[];$args=[];$q=trim($_GET['q']??'');$status=$_GET['status']??'';$cat=(int)($_GET['kategori']??0);$from=$_GET['dari']??'';$to=$_GET['sampai']??'';if(me()['role']==='petugas'){$where[]='r.id_petugas=?';$args[]=me()['id_user'];}if($q!==''){$where[]='(r.nomor_laporan LIKE ? OR r.judul LIKE ? OR u.nama_lengkap LIKE ?)';array_push($args,'%'.$q.'%','%'.$q.'%','%'.$q.'%');}if(in_array($status,status_options(),true)){$where[]='r.status=?';$args[]=$status;}if($cat>0){$where[]='r.id_kategori=?';$args[]=$cat;}if($from!==''&&valid_date_format($from)){$where[]='DATE(r.created_at)>=?';$args[]=$from;}if($to!==''&&valid_date_format($to)){$where[]='DATE(r.created_at)<=?';$args[]=$to;}$sql='SELECT r.nomor_laporan,r.judul,u.nama_lengkap,c.nama_kategori,r.lokasi_kejadian,r.tanggal_kejadian,r.status,r.created_at FROM reports r JOIN users u ON u.id_user=r.id_pelapor JOIN categories c ON c.id_kategori=r.id_kategori';if($where)$sql.=' WHERE '.implode(' AND ',$where);$sql.=' ORDER BY r.created_at DESC';$s=db()->prepare($sql);$s->execute($args);header('Content-Type: text/csv; charset=utf-8');header('Content-Disposition: attachment; filename="laporwarga-laporan-'.date('Ymd-His').'.csv"');$out=fopen('php://output','w');fwrite($out,"\xEF\xBB\xBF");fputcsv($out,['Nomor Laporan','Judul','Pelapor','Kategori','Lokasi','Tanggal Kejadian','Status','Tanggal Dibuat']);while($r=$s->fetch())fputcsv($out,array_map(fn($v)=>is_string($v)&&preg_match('/^[=+@\-]/',$v)?"'".$v:$v,array_values($r)));fclose($out);log_activity('ekspor_csv','Ekspor laporan');exit;